message.content:
{
  "gate_token": "x6-57n6DcAf08co7h9VV9Q",
  "title": "The Mirror Road Through the Broken City",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team gathers at the edge of the ruined city.",
      "visual_description": "A cracked stone overlook at dusk, broken spires in the distance, an unrolled map weighed down by a brass compass, lantern light pooling on torn banners.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "The lamp warns of a trap hidden inside the welcome.",
      "visual_description": "Close-up of an oil lamp with a single glowing eye in its flame, casting nervous shadows on a mapmaker's ink-stained sleeve.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "A clockwork scout slips beneath the great castle gates.",
      "visual_description": "Massive iron-banded gates standing ajar, vines curling through the bars, a small metal fox with a key-wind tail darting through a gap, blue glass eyes glinting.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The diver arrives through a shattered stained-glass window.",
      "visual_description": "A figure in a clear diving helmet emerging from a tall broken window, coat shimmering with reflected city lights, shards suspended mid-fall around him.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Mara plots a route past the cursed tower.",
      "visual_description": "A leaning black tower wrapped in chains of green fire, the cartographer kneeling on cobblestones drawing a chalk path, brass compass spinning wildly.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "Frightened townsfolk press into doorways as the team passes.",
      "visual_description": "Narrow ruined street, pale faces peeking from boarded windows, the team moving in single file beneath fluttering torn royal banners.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "An armored patrol clatters across the plaza ahead.",
      "visual_description": "A wide cracked plaza ringed by toppled statues, distant silhouettes in plate armor marching past a dry fountain, the team crouched behind a fallen banner.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "They find the official they were sent to retrieve, fast asleep.",
      "visual_description": "A dusty records office, a plump figure slumped over a ledger-book pillow, stamped papers stuck to his sleeves and cheek, candle long since melted.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "The lamp insists the sleeper holds the key to the city's curse.",
      "visual_description": "The glowing-eyed lamp hovering close to the sleeping official's pocket, illuminating a wax seal stamped with a tower-and-bridge crest.",
      "characters": ["oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "The fox scouts ahead and signals a dragon-rumor in the smoke.",
      "visual_description": "Smoke curling from a collapsed roof shaped vaguely like a long serpent, the clockwork fox perched on a gargoyle, tail spinning a warning code.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The diver dives through a mirror to take a shortcut.",
      "visual_description": "A tall cracked silver mirror in a ballroom, the diving figure half-submerged in its surface like water, coat reflecting a hundred broken chandeliers.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door demands an answer in three voices.",
      "visual_description": "An arched door of humming blue stone carved with three masks, the cartographer holding up the lamp, the fox standing at her boot, runes glowing faintly.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The sleeper mumbles the password without waking.",
      "visual_description": "The official drooling onto his ledger as he's carried past the door, garbled syllables drawn as smoky letters that match the masks above.",
      "characters": ["sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Old royal banners come loose and tangle the patrol behind them.",
      "visual_description": "A long colonnade where torn crimson banners drop from rafters onto pursuing armored figures, the team running through shafts of dust-lit light.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The cursed tower cracks and breathes fire above the rooftops.",
      "visual_description": "Distant tower splitting like an eggshell, a long plume of orange flame uncoiling against the night sky, reflected in the diver's helmet.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Mara spots the river bridge marked in red on her map.",
      "visual_description": "A rain-slick rooftop, the cartographer pointing toward a long stone bridge spanning a black river, compass needle locked steady at last.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the bridge as the stones fall behind them.",
      "visual_description": "An ancient arched bridge with sections collapsing into the river, the team mid-stride, the fox leaping a gap, the diver carrying the still-snoring official.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far bank, the lamp finally lets its eye close.",
      "visual_description": "Pre-dawn riverbank, the ruined city glowing across the water, the team seated on roots, the lamp's flame dimming to a soft wink as the official keeps sleeping.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

